CREATE OR REPLACE FUNCTION public.persist_invoice_reference_journal_link_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_journal_id uuid;
  v_journal_count integer;
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT
    (array_agg(entry.id ORDER BY entry.id))[1],
    count(*)
  INTO v_journal_id, v_journal_count
  FROM public.journal_entries entry
  WHERE entry.company_id = NEW.company_id
    AND entry.reference_type = 'invoice'
    AND entry.reference_id = NEW.id;

  IF v_journal_count > 1 THEN
    RAISE EXCEPTION 'Invoice % has multiple reference journals', NEW.id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_journal_count = 1 THEN
    NEW.journal_entry_id := v_journal_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_invoice_journal_entry_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_number text;
  v_journal_id uuid;
  v_ar_account_id uuid;
  v_revenue_account_id uuid;
  v_tax_account_id uuid;
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_journal_id
  FROM public.journal_entries
  WHERE company_id = NEW.company_id
    AND reference_type = 'invoice'
    AND reference_id = NEW.id
  ORDER BY created_at ASC NULLS LAST
  LIMIT 1;

  IF v_journal_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT am.chart_of_accounts_id INTO v_ar_account_id
  FROM public.account_mappings am
  JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
  WHERE am.company_id = NEW.company_id
    AND dat.type_code = 'RECEIVABLES'
    AND am.is_active = true
  LIMIT 1;

  SELECT am.chart_of_accounts_id INTO v_revenue_account_id
  FROM public.account_mappings am
  JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
  WHERE am.company_id = NEW.company_id
    AND dat.type_code IN ('RENTAL_REVENUE', 'SALES_REVENUE', 'REVENUE')
    AND am.is_active = true
  ORDER BY
    CASE dat.type_code
      WHEN 'RENTAL_REVENUE' THEN 1
      WHEN 'SALES_REVENUE' THEN 2
      WHEN 'REVENUE' THEN 3
      ELSE 4
    END
  LIMIT 1;

  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_entry_number := 'INV-' || to_char(COALESCE(NEW.invoice_date, CURRENT_DATE), 'YYYYMMDD') || '-' || substring(NEW.id::text, 1, 8);

  INSERT INTO public.journal_entries (
    company_id, entry_number, entry_date, description,
    total_debit, total_credit, status, reference_type, reference_id, created_by
  )
  VALUES (
    NEW.company_id, v_entry_number,
    COALESCE(NEW.invoice_date, CURRENT_DATE),
    'Invoice: ' || COALESCE(NEW.invoice_number, NEW.id::text),
    NEW.total_amount, NEW.total_amount, 'draft', 'invoice', NEW.id, NEW.created_by
  )
  RETURNING id INTO v_journal_id;

  INSERT INTO public.journal_entry_lines (journal_entry_id, account_id, line_number, line_description, debit_amount, credit_amount)
  VALUES
    (v_journal_id, v_ar_account_id, 1, 'Customer receivable', NEW.total_amount, 0),
    (v_journal_id, v_revenue_account_id, 2, 'Service revenue', 0, COALESCE(NEW.subtotal, NEW.total_amount - COALESCE(NEW.tax_amount, 0)));

  IF COALESCE(NEW.tax_amount, 0) > 0 THEN
    SELECT am.chart_of_accounts_id INTO v_tax_account_id
    FROM public.account_mappings am
    JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
    WHERE am.company_id = NEW.company_id
      AND dat.type_code IN ('TAX_PAYABLE', 'VAT_PAYABLE', 'TAX')
      AND am.is_active = true
    LIMIT 1;

    IF v_tax_account_id IS NOT NULL THEN
      INSERT INTO public.journal_entry_lines (journal_entry_id, account_id, line_number, line_description, debit_amount, credit_amount)
      VALUES (v_journal_id, v_tax_account_id, 3, 'Collected tax', 0, NEW.tax_amount);
    END IF;
  END IF;

  UPDATE public.journal_entries
  SET status = 'posted', posted_by = NEW.created_by, posted_at = now(), updated_at = now()
  WHERE id = v_journal_id;

  NEW.journal_entry_id := v_journal_id;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_invoice_date_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_contract_start_date date;
BEGIN
  IF NEW.contract_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT start_date INTO v_contract_start_date
  FROM public.contracts
  WHERE id = NEW.contract_id;

  IF v_contract_start_date IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.contract_id IS NOT DISTINCT FROM OLD.contract_id
      AND NEW.invoice_date IS NOT DISTINCT FROM OLD.invoice_date
      AND NEW.due_date IS NOT DISTINCT FROM OLD.due_date THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Only block if invoice_date month is BEFORE contract start month (allow same month)
  IF NEW.invoice_date IS NOT NULL AND DATE_TRUNC('month', NEW.invoice_date) < DATE_TRUNC('month', v_contract_start_date) THEN
    RAISE EXCEPTION 'Invoice date (%) cannot be before contract start date (%)',
      NEW.invoice_date, v_contract_start_date;
  END IF;

  IF NEW.due_date IS NOT NULL AND DATE_TRUNC('month', NEW.due_date) < DATE_TRUNC('month', v_contract_start_date) THEN
    RAISE EXCEPTION 'Invoice due date (%) cannot be before contract start date (%)',
      NEW.due_date, v_contract_start_date;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.system_generate_invoice_for_contract_month_core(p_contract_id uuid, p_invoice_month date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_contract public.contracts%ROWTYPE;
  v_invoice_id uuid;
  v_invoice_number varchar(50);
  v_total_amount numeric(15,3);
  v_invoice_date date;
  v_schedule_id uuid;
  v_actor uuid := auth.uid();
  v_company_currency text;
  v_month date := date_trunc('month', p_invoice_month)::date;
BEGIN
  SELECT contract.*
  INTO v_contract
  FROM public.contracts contract
  WHERE contract.id = p_contract_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contract not found: %', p_contract_id USING ERRCODE = 'P0001';
  END IF;

  IF v_contract.start_date > (v_month + interval '1 month - 1 day')::date
     OR v_contract.end_date < v_month
  THEN
    RETURN NULL;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_contract.company_id::text || ':invoice:' || to_char(v_month, 'YYYY-MM'),
      0
    )
  );

  IF EXISTS (
    SELECT 1
    FROM public.invoices invoice
    WHERE invoice.company_id = v_contract.company_id
      AND invoice.contract_id = v_contract.id
      AND date_trunc(
        'month',
        COALESCE(invoice.invoice_month, invoice.invoice_date)::timestamp without time zone
      )::date = v_month
      AND lower(COALESCE(invoice.status, '')) NOT IN (
        'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
      )
      AND lower(COALESCE(invoice.payment_status, '')) NOT IN (
        'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
      )
  ) THEN
    RETURN NULL;
  END IF;

  SELECT schedule.id, schedule.amount, schedule.due_date
  INTO v_schedule_id, v_total_amount, v_invoice_date
  FROM public.contract_payment_schedules schedule
  WHERE schedule.contract_id = v_contract.id
    AND schedule.company_id = v_contract.company_id
    AND date_trunc('month', schedule.due_date)::date = v_month
    AND COALESCE(schedule.amount, 0) > 0.01
    AND lower(COALESCE(schedule.status, '')) NOT IN (
      'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
    )
  ORDER BY schedule.installment_number NULLS LAST, schedule.due_date, schedule.id
  LIMIT 1
  FOR UPDATE OF schedule;

  IF v_schedule_id IS NULL OR COALESCE(v_total_amount, 0) <= 0.01 THEN
    RAISE EXCEPTION 'Contract month requires one positive active schedule'
      USING ERRCODE = 'P0001';
  END IF;

  v_invoice_date := greatest(v_invoice_date, v_contract.start_date);

  SELECT COALESCE(NULLIF(company.currency, ''), 'QAR')
  INTO v_company_currency
  FROM public.companies company
  WHERE company.id = v_contract.company_id;

  SELECT 'INV-' || to_char(v_month, 'YYYYMM') || '-' ||
         lpad((COALESCE(MAX(CAST(substring(invoice.invoice_number FROM 'INV-[0-9]{6}-([0-9]+)') AS integer)), 0) + 1)::text, 5, '0')
  INTO v_invoice_number
  FROM public.invoices invoice
  WHERE invoice.company_id = v_contract.company_id
    AND invoice.invoice_number LIKE 'INV-' || to_char(v_month, 'YYYYMM') || '-%';

  INSERT INTO public.invoices (
    company_id, customer_id, contract_id, cost_center_id, invoice_number,
    invoice_date, invoice_month, due_date, total_amount, subtotal, tax_amount,
    discount_amount, paid_amount, balance_due, status, payment_status,
    invoice_type, currency, notes, created_by, created_at, updated_at
  ) VALUES (
    v_contract.company_id, v_contract.customer_id, v_contract.id, v_contract.cost_center_id,
    v_invoice_number, v_invoice_date, v_month, v_invoice_date,
    v_total_amount, v_total_amount, 0, 0, 0, v_total_amount,
    'sent', 'unpaid', 'service', COALESCE(v_company_currency, 'QAR'),
    'Generated for contract billing month ' || to_char(v_month, 'YYYY-MM'),
    v_actor, now(), now()
  )
  RETURNING id INTO v_invoice_id;

  INSERT INTO public.invoice_items (
    invoice_id, line_number, item_description, item_description_ar,
    quantity, unit_price, line_total, tax_rate, tax_amount, cost_center_id
  ) VALUES (
    v_invoice_id, 1,
    'Monthly rental payment - ' || to_char(v_month, 'YYYY-MM'),
    'قسط إيجار شهري - ' || to_char(v_month, 'YYYY-MM'),
    1, v_total_amount, v_total_amount, 0, 0, v_contract.cost_center_id
  );

  UPDATE public.contract_payment_schedules schedule
  SET invoice_id = v_invoice_id,
      updated_at = now()
  WHERE schedule.id = v_schedule_id
    AND schedule.company_id = v_contract.company_id
    AND schedule.contract_id = v_contract.id;

  RETURN v_invoice_id;
END;
$function$
